+/** Selects a supported Accept-Language preference, or the configured fallback. */
+export function requestLanguage(header, fallback = "en") {
+  if (Array.isArray(header)) header = header.join(",");
+  if (typeof header !== "string") return fallback;
+  let language = fallback;
+  let bestQuality = 0;
+  for (const entry of header.split(",")) {
+    const match = /^\s*([a-z]+(?:-[a-z0-9]+)*)(?:\s*;\s*q\s*=\s*(0(?:\.\d{0,3})?|1(?:\.0{0,3})?))?\s*$/i.exec(entry);
+    if (!match) continue;
+    const base = match[1].toLowerCase().split("-")[0];
+    const quality = match[2] === undefined ? 1 : Number(match[2]);
+    if (LANGUAGES.includes(base) && quality > bestQuality) {
+      language = base;
+      bestQuality = quality;
+    }
+  }
+  return language;
+}
